"use client";

import { useState } from "react";
import { motion } from "framer-motion";
import { RevealSection } from "@/components/ui/RevealSection";
import {
  MapPin,
  Phone,
  Mail,
  Clock,
  Send,
  CheckCircle,
  Shield,
  Users,
  Globe,
} from "lucide-react";

const trustPoints = [
  { icon: Shield, text: "Données hébergées en Suisse" },
  { icon: Users, text: "Équipe trilingue FR / DE / IT" },
  { icon: Globe, text: "26 cantons couverts" },
  { icon: Clock, text: "Réponse sous 24h ouvrées" },
];

const formFields = [
  { id: "prenom", label: "Prénom *", type: "text", placeholder: "Votre prénom" },
  { id: "nom", label: "Nom *", type: "text", placeholder: "Votre nom" },
  { id: "email", label: "Email professionnel *", type: "email", placeholder: "prenom@organisation.ch", full: true },
  { id: "organisation", label: "Organisation *", type: "text", placeholder: "Nom de votre OSAD / Spitex", full: true },
  { id: "role", label: "Votre rôle", type: "text", placeholder: "Ex : Directeur, Responsable planification…", full: true },
  { id: "telephone", label: "Téléphone", type: "tel", placeholder: "+41 xx xxx xx xx" },
  { id: "canton", label: "Canton", type: "text", placeholder: "Ex : Vaud, Valais, Zurich…" },
];

export default function ContactSection() {
  const [submitted, setSubmitted] = useState(false);
  const [loading, setLoading] = useState(false);
  const [formData, setFormData] = useState<Record<string, string>>({});
  const [interest, setInterest] = useState<string[]>([]);

  const interests = ["Planification", "Team Planner", "L'IA dans les soins", "Cockpit", "Factoring", "Dossier clinique"];

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setLoading(true);
    await new Promise((r) => setTimeout(r, 1200));
    setLoading(false);
    setSubmitted(true);
  };

  const toggleInterest = (item: string) => {
    setInterest((prev) =>
      prev.includes(item) ? prev.filter((i) => i !== item) : [...prev, item]
    );
  };

  return (
    <>
      {/* Hero */}
      <section className="relative overflow-hidden pt-32 pb-16 lg:pt-40 lg:pb-20">
        <div className="absolute inset-0 bg-gradient-to-br from-neutral-950 via-neutral-900 to-brand-950" />
        <div
          className="absolute inset-0 opacity-[0.04]"
          style={{
            backgroundImage: "linear-gradient(rgba(255,255,255,0.5) 1px, transparent 1px), linear-gradient(90deg, rgba(255,255,255,0.5) 1px, transparent 1px)",
            backgroundSize: "48px 48px",
          }}
        />
        <div className="container-medlink relative z-10 text-center">
          <RevealSection>
            <span className="badge-brand-dark mb-5">Contactez-nous</span>
            <h1 className="text-display-xl text-white mb-4 font-display">
              Planifions votre
              <span className="gradient-text-dark block">démonstration</span>
            </h1>
            <p className="text-white/65 text-lg max-w-xl mx-auto">
              Notre équipe vous accompagne pour découvrir MedLink et évaluer comment la plateforme peut répondre à vos besoins spécifiques.
            </p>
          </RevealSection>
        </div>
      </section>

      {/* Main */}
      <section className="section-py bg-neutral-50">
        <div className="container-medlink">
          <div className="grid lg:grid-cols-5 gap-10">
            {/* Left: info */}
            <div className="lg:col-span-2 space-y-6">
              <RevealSection direction="left">
                {/* Trust */}
                <div className="card-premium p-6 mb-6">
                  <h3 className="font-bold text-neutral-900 mb-4 text-sm uppercase tracking-wider">
                    Pourquoi nous contacter
                  </h3>
                  <ul className="space-y-3.5">
                    {trustPoints.map((t) => {
                      const Icon = t.icon;
                      return (
                        <li key={t.text} className="flex items-center gap-3">
                          <div className="w-8 h-8 rounded-lg bg-brand-50 flex items-center justify-center flex-shrink-0">
                            <Icon size={15} className="text-brand-600" />
                          </div>
                          <span className="text-sm text-neutral-700 font-medium">{t.text}</span>
                        </li>
                      );
                    })}
                  </ul>
                </div>

                {/* Offices */}
                <div className="space-y-4">
                  {[
                    { city: "Nyon (siège)", address: "Route de Saint-Cergue 41\n1260 Nyon VD" },
                    { city: "Sion", address: "Avenue de Pratifori 22\n1950 Sion VS" },
                  ].map((office) => (
                    <div key={office.city} className="card-premium p-5 flex items-start gap-4">
                      <div className="w-9 h-9 rounded-xl bg-brand-50 flex items-center justify-center flex-shrink-0">
                        <MapPin size={16} className="text-brand-600" />
                      </div>
                      <div>
                        <p className="font-bold text-neutral-900 text-sm">{office.city}</p>
                        <p className="text-xs text-neutral-500 whitespace-pre-line">{office.address}</p>
                      </div>
                    </div>
                  ))}

                  <div className="card-premium p-5 flex items-center gap-4">
                    <div className="w-9 h-9 rounded-xl bg-brand-50 flex items-center justify-center flex-shrink-0">
                      <Mail size={16} className="text-brand-600" />
                    </div>
                    <a href="mailto:info@medlink.ch" className="text-sm font-semibold text-brand-600 hover:text-brand-700">
                      info@medlink.ch
                    </a>
                  </div>
                </div>
              </RevealSection>
            </div>

            {/* Right: form */}
            <div className="lg:col-span-3">
              <RevealSection direction="right" delay={0.1}>
                <div className="card-premium p-8 lg:p-10">
                  {submitted ? (
                    <motion.div
                      initial={{ opacity: 0, scale: 0.95 }}
                      animate={{ opacity: 1, scale: 1 }}
                      className="text-center py-8"
                    >
                      <div className="w-16 h-16 rounded-full bg-green-50 flex items-center justify-center mx-auto mb-5">
                        <CheckCircle size={32} className="text-green-500" />
                      </div>
                      <h3 className="text-xl font-bold text-neutral-900 mb-3">
                        Demande envoyée !
                      </h3>
                      <p className="text-neutral-500 text-sm max-w-sm mx-auto">
                        Notre équipe vous contactera sous 24h ouvrées pour planifier votre démonstration personnalisée.
                      </p>
                    </motion.div>
                  ) : (
                    <form onSubmit={handleSubmit}>
                      <h2 className="text-xl font-bold text-neutral-900 mb-1">
                        Demande de démonstration
                      </h2>
                      <p className="text-sm text-neutral-500 mb-7">
                        Complétez ce formulaire et notre équipe vous recontacte sous 24h.
                      </p>

                      <div className="grid grid-cols-1 sm:grid-cols-2 gap-4 mb-5">
                        {formFields.map((field) => (
                          <div key={field.id} className={field.full ? "sm:col-span-2" : ""}>
                            <label className="block text-xs font-semibold text-neutral-700 mb-1.5">
                              {field.label}
                            </label>
                            <input
                              type={field.type}
                              id={field.id}
                              placeholder={field.placeholder}
                              value={formData[field.id] || ""}
                              onChange={(e) =>
                                setFormData((prev) => ({ ...prev, [field.id]: e.target.value }))
                              }
                              className="w-full px-4 py-2.5 rounded-lg border border-neutral-200 text-sm text-neutral-900 placeholder-neutral-400 focus:outline-none focus:border-brand-400 focus:ring-2 focus:ring-brand-100 transition-all"
                            />
                          </div>
                        ))}
                      </div>

                      {/* Interests */}
                      <div className="mb-5">
                        <p className="text-xs font-semibold text-neutral-700 mb-2.5">
                          Modules d&apos;intérêt
                        </p>
                        <div className="flex flex-wrap gap-2">
                          {interests.map((item) => (
                            <button
                              key={item}
                              type="button"
                              onClick={() => toggleInterest(item)}
                              className={`px-3 py-1.5 rounded-full text-xs font-semibold border transition-all ${
                                interest.includes(item)
                                  ? "bg-brand-500 text-white border-brand-500"
                                  : "bg-white text-neutral-600 border-neutral-200 hover:border-brand-300 hover:text-brand-600"
                              }`}
                            >
                              {item}
                            </button>
                          ))}
                        </div>
                      </div>

                      {/* Message */}
                      <div className="mb-6">
                        <label className="block text-xs font-semibold text-neutral-700 mb-1.5">
                          Message / contexte
                        </label>
                        <textarea
                          rows={3}
                          placeholder="Décrivez brièvement votre organisation et vos besoins…"
                          className="w-full px-4 py-2.5 rounded-lg border border-neutral-200 text-sm text-neutral-900 placeholder-neutral-400 focus:outline-none focus:border-brand-400 focus:ring-2 focus:ring-brand-100 transition-all resize-none"
                        />
                      </div>

                      <button
                        type="submit"
                        disabled={loading}
                        className="btn-primary w-full justify-center text-base py-3.5 disabled:opacity-70"
                      >
                        {loading ? (
                          <span className="flex items-center gap-2">
                            <span className="w-4 h-4 border-2 border-white/30 border-t-white rounded-full animate-spin" />
                            Envoi en cours…
                          </span>
                        ) : (
                          <span className="flex items-center gap-2">
                            <Send size={16} />
                            Demander une démonstration
                          </span>
                        )}
                      </button>
                      <p className="text-xs text-neutral-400 text-center mt-3">
                        Sans engagement · Démo personnalisée gratuite · Réponse sous 24h
                      </p>
                    </form>
                  )}
                </div>
              </RevealSection>
            </div>
          </div>
        </div>
      </section>
    </>
  );
}
